import numpy as np
from scipy.special import erf
F=np.load('feats.npz'); y=F['y']; FOLDS=np.load('folds_rep.npy')
C9=F['C9'].astype(np.float64); M9=F['M9'].astype(np.float64); M0=F['M0'].astype(np.float64)
def gelu(z): return 0.5*z*(1+erf(z/np.sqrt(2)))
def stdz(X,tr): m=X[tr].mean(0); s=X[tr].std(0)+1e-6; return (X-m)/s
def ridge_W(Xtr,Y,lam):
    xm=Xtr.mean(0); Xc=Xtr-xm; ym=Y.mean(0); n,d=Xc.shape
    if d<=n: Wt=np.linalg.solve(Xc.T@Xc+lam*np.eye(d),Xc.T@(Y-ym))
    else: Wt=Xc.T@np.linalg.solve(Xc@Xc.T+lam*np.eye(n),Y-ym)
    return Wt, ym-xm@Wt
def lda_stash(tr,kr=0.1):
    X=M0; mu=X[tr].mean(0); Xs=X-mu
    Mc=np.array([Xs[tr][y[tr]==c].mean(0) for c in range(8)])
    R=Xs[tr]-Mc[y[tr]]; Sw=R.T@R/len(R)
    W=np.linalg.solve(Sw+kr*np.trace(Sw)/768*np.eye(768),Mc.T); P=Xs@W; return P/P[tr].std(0)
def joint_stash(tr,lam=1000):
    Z=np.concatenate([stdz(C9,tr),stdz(M9,tr),stdz(M0,tr)],1)
    Wt,b=ridge_W(Z[tr],np.eye(8)[y[tr]]-1/8,lam)
    P=Z[:,1536:]@Wt[1536:]; return P/P[tr].std(0)
rng=np.random.default_rng(0)
def run(stash_fn, lams, w=1.0, noise=0.0, kern=None):
    res={l:0 for l in lams}
    for fo in FOLDS:
        for f in range(5):
            tr=fo!=f; te=fo==f
            parts=[stdz(C9,tr),stdz(M9,tr)]
            if stash_fn is not None:
                S=stash_fn(tr); al=np.exp(noise*rng.standard_normal(len(y)))[:,None]; S=S*al
                parts.append(w*stdz(S,tr))
            X=np.concatenate(parts,1)
            if kern is not None:
                beta,theta,wl=kern
                Xn=X/np.linalg.norm(X,axis=1,keepdims=True)
                Kf=gelu(beta*(Xn@Xn[tr].T)-theta); X=np.concatenate([wl*X,Kf],1)
            Wt,b=None,None
            Y=np.eye(8)[y[tr]]-1/8
            for l in lams:
                Wt,b=ridge_W(X[tr],Y,l); res[l]+=((X[te]@Wt+b).argmax(1)==y[te]).sum()
    return {l:round(res[l]/len(y)/len(FOLDS),4) for l in lams}
print('joint stash w1', run(joint_stash,[300,1000],1))
print('joint stash w2', run(joint_stash,[300,1000],2))
for nz in [0.1,0.2,0.3]:
    print('LDA stash noise',nz, run(lda_stash,[300,1000],1,nz))
print('kernel no stash', run(None,[10,30],kern=(10,4.5,0.3)))
print('kernel + LDA stash', run(lda_stash,[10,30],1,0.0,kern=(10,4.5,0.3)))
print('kernel + LDA stash noise .2', run(lda_stash,[10,30],1,0.2,kern=(10,4.5,0.3)))
